import java.util.*;
import java.io.*;

public class Cutting{

    public static int[] convertStringToIntArray(String s){
        String[] parts = s.trim().split("\\s+");
        int[] result = new int[parts.length];
        for(int i=0; i<parts.length; i++){
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    boolean isBalancedSubArray(int[] array, int index){
        int evenCount = 0, oddCount = 0;
        for(int i=0; i<=index; i++){
            if(array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findOptimalCutIndex(int[] array, int coinsRemaining, Map<Integer,Boolean> usedCuts){
        int bestIndex = -1;
        int bestCost = coinsRemaining + 1;
        for(int i=1; i<array.length - 1; i++){
            int cost = Math.abs(array[i] - array[i+1]);
            if(cost < bestCost && isBalancedSubArray(array, i) && !usedCuts.containsKey(i)){
                bestCost = cost;
                bestIndex = i;
            }
        }
        return bestIndex;
    }

    public int computeMaxCuts(int n, int b, int[] a){
        int coinsLeft = b;
        int totalCuts = 0;
        Map<Integer,Boolean> usedIndices = new HashMap<>();
        while(coinsLeft > 0){
            int index = findOptimalCutIndex(a, coinsLeft, usedIndices);
            if(index >= 0){
                usedIndices.put(index, true);
                int cost = Math.abs(a[index] - a[index+1]);
                coinsLeft -= cost;
                totalCuts++;
            } else {
                break;
            }
        }
        return totalCuts;
    }

    public static void main(String[] args) throws Exception{
        Scanner sc = new Scanner(System.in);
        String line1 = sc.nextLine();
        String line2 = sc.nextLine();
        int[] nB = convertStringToIntArray(line1);
        int[] a = convertStringToIntArray(line2);
        Cutting c = new Cutting();
        int n = nB[0];
        int b = nB[1];
        System.out.println(c.computeMaxCuts(n, b, a));
        sc.close();
    }
}
