def convert_string_to_int_list(s):
    return list(map(int, s.strip().split()))

def is_balanced_sub_array(array, index):
    even_count = 0
    odd_count = 0
    for i in range(index + 1):
        if array[i] % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return even_count == odd_count

def find_optimal_cut_index(array, coins_remaining, used_cuts):
    best_index = -1
    best_cost = coins_remaining + 1
    for i in range(1, len(array) - 1):
        cost = abs(array[i] - array[i + 1])
        if cost < best_cost and is_balanced_sub_array(array, i) and i not in used_cuts:
            best_cost = cost
            best_index = i
    return best_index

def compute_max_cuts(n, b, a):
    coins_left = b
    total_cuts = 0
    used_indices = set()
    while coins_left > 0:
        index = find_optimal_cut_index(a, coins_left, used_indices)
        if index >= 0:
            used_indices.add(index)
            cost = abs(a[index] - a[index + 1])
            coins_left -= cost
            total_cuts += 1
        else:
            break
    return total_cuts

def main():
    line1 = input()
    line2 = input()
    n_b = convert_string_to_int_list(line1)
    a = convert_string_to_int_list(line2)
    n = n_b[0]
    b = n_b[1]
    print(compute_max_cuts(n, b, a))

if __name__ == "__main__":
    main()

